scripts.script:
if game:GetService("CoreGui"):FindFirstChild("ToraScript") then
    game:GetService("CoreGui").ToraScript:Destroy()
end

local Library = loadstring(game:HttpGet("https://raw.githubusercontent.com/liebertsx/Tora-Library/main/src/librarynew", true))()
local Window = Library:CreateWindow("Plant Evolution")

Window:AddButton({
    text = "INF WINS",
    flag = "button",
    callback = function()
        game:GetService("ReplicatedStorage").Remote.Event.Egg.OpenEgg:FireServer(unpack({
            20,
            -50
        }))
    end
})

Window:AddButton({
    text = "Buy Best Eggs (20Aa)",
    flag = "button",
    callback = function()
        game:GetService("ReplicatedStorage").Remote.Event.Egg.OpenEgg:FireServer(unpack({
            20,
            3
        }))
    end
})

Window:AddButton({
    text = "+1 Pet Slot",
    flag = "button",
    callback = function()
        game:GetService("ReplicatedStorage").Remote.Event.Activity.ActivityBuy:FireServer(unpack({
            3
        }))
    end
})

Window:AddButton({
    text = "Get OP Pets",
    flag = "button",
    callback = function()
        game:GetService("ReplicatedStorage").Remote.Event.Activity.ActivityBuy:FireServer(unpack({
            2
        }))
    end
})

Window:AddButton({
    text = "Inf Spin",
    flag = "button",
    callback = function()
        game:GetService("ReplicatedStorage").Remote.Function.Activity.TryDoSpin:InvokeServer(unpack({
            -100
        }))
        game:GetService("ReplicatedStorage").Remote.Function.Activity.TryDoSpin:InvokeServer(unpack({
            100
        }))
    end
})

Window:AddLabel({
    text = "YouTube: Tora IsMe"
})

Library:Init()

if game:GetService("CoreGui"):FindFirstChild("ToraScript") then
    game:GetService("CoreGui").ToraScript:Destroy()
end

local Library = loadstring(game:HttpGet("https://raw.githubusercontent.com/liebertsx/Tora-Library/main/src/librarynew", true))()
local Window = Library:CreateWindow("Boxing Battles")

Window:AddButton({
    text = "+1,000 Strength",
    flag = "button",
    callback = function()
        game.MarketplaceService:SignalPromptProductPurchaseFinished(game.Players.LocalPlayer.UserId, 3401104082, true)
    end,
})

Window:AddButton({
    text = "+10,000 Strength",
    flag = "button",
    callback = function()
        game.MarketplaceService:SignalPromptProductPurchaseFinished(game.Players.LocalPlayer.UserId, 3401104226, true)
    end,
})

Window:AddButton({
    text = "+100,000 Strength",
    flag = "button",
    callback = function()
        game.MarketplaceService:SignalPromptProductPurchaseFinished(game.Players.LocalPlayer.UserId, 3401104347, true)
    end,
})

Window:AddButton({
    text = "+1,000,000 Strength",
    flag = "button",
    callback = function()
        game.MarketplaceService:SignalPromptProductPurchaseFinished(game.Players.LocalPlayer.UserId, 3401104590, true)
    end,
})

Window:AddButton({
    text = "Instant Rebirth",
    flag = "button",
    callback = function()
        game.MarketplaceService:SignalPromptProductPurchaseFinished(game.Players.LocalPlayer.UserId, 3401108845, true)
    end,
})

Window:AddButton({
    text = "Scare All",
    flag = "button",
    callback = function()
        game.MarketplaceService:SignalPromptProductPurchaseFinished(game.Players.LocalPlayer.UserId, 3450911952, true)
    end,
})

Window:AddToggle({
    text = "Spam Strength",
    flag = "toggle",
    state = false,
    callback = function(state)
        _G.Strength = state
        print("Strength: ", state)
        if state then
            Strength()
        end
    end,
})

function Strength()
    spawn(function()
        _G.Strength = true
        while _G.Strength do
            wait()
            pcall(function()
                game.MarketplaceService:SignalPromptProductPurchaseFinished(game.Players.LocalPlayer.UserId, 3401104590, true)
                wait()
            end)
        end
    end)
end

Window:AddLabel({ text = "YouTube: Tora IsMe" })
Library:Init()
